"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[68957],{70137:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"BurstCannonConfig","desc":"Tuning for the train-mounted BurstCannon (tier 3, energy line: four-barrel, hold\\nto fire 4-shot bursts). Shared by the server (`BurstCannonServer`), the client\\ncontroller and `BurstCannonMath`. It runs the shared shell-turret code in **heat\\nmode** (`HeatPerShot` set: heat and overheat, no magazine or reload; see\\n`EnergyCannonMath`) and keeps its splash shells (`BlastRadius > 0`).\\nAll sound keys resolve through SoundManager/SoundConfig. Angles here are in\\ndegrees unless the name says otherwise; `BurstCannonMath` works in radians.","source":{"line":13,"path":"src/ReplicatedStorage/SharedModules/Configs/BurstCannonConfig.luau"}}')}}]);